//! T6 验收测试：声学特征前端（fbank + LFR + CMVN）与 Python funasr-onnx `extract_feat` 的 golden 对拍。
//!
//! golden 全部来自 `reference/dump_golden.py` 用参考实现跑出来的原样输出：
//! * `tests/golden/input/{fixture}/input.s16bin`：送进引擎的同一份 16k 单声道 s16le PCM；
//! * `tests/golden/sensevoice/{fixture}/feats.f32bin`（= 段 0 的副本）与
//!   `spans/span_NNN/feats.f32bin`：整段 `extract_feat` 的输出，形状 (feats_len, 560)。
//!
//! 判定标准：逐元素绝对误差 ≤ 1e-4（`ATOL`），并打印每个 fixture / 每个 span 的实测最大误差。
//! CMVN 统计量内嵌在文件末尾（见 `AM_MVN_TXT`），因此本测试完全离线，不需要模型文件。

use std::io;
use std::path::{Path, PathBuf};

use ndarray::Array2;
use serde_json::Value;

use funasr_subtitle_rs::frontend::{
    Cmvn, Features, extract_features, load_cmvn, paraformer_frontend, sensevoice_frontend,
};

type TestResult = Result<(), Box<dyn std::error::Error>>;

/// 逐元素绝对误差上限（golden 为 float32）。
const ATOL: f32 = 1e-4;
const FIXTURES: [&str; 3] = ["sample_zh", "sample_en_runon", "sample_long"];
const SR: i64 = 16_000;

fn golden_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("golden")
}

fn read_s16(path: &Path) -> io::Result<Vec<i16>> {
    let bytes = std::fs::read(path)?;
    Ok(bytes
        .as_chunks::<2>()
        .0
        .iter()
        .map(|c| i16::from_le_bytes(*c))
        .collect())
}

fn read_f32(path: &Path) -> io::Result<Vec<f32>> {
    let bytes = std::fs::read(path)?;
    Ok(bytes
        .as_chunks::<4>()
        .0
        .iter()
        .map(|c| f32::from_le_bytes(*c))
        .collect())
}

fn read_json(path: &Path) -> Result<Value, Box<dyn std::error::Error>> {
    let text = std::fs::read_to_string(path)?;
    Ok(serde_json::from_str(&text)?)
}

/// 参考实现的 am.mvn（模型目录里那一份；golden 是用它做 CMVN 的）。
fn golden_cmvn() -> Result<Cmvn, Box<dyn std::error::Error>> {
    let dir = tempfile::tempdir()?;
    let path = dir.path().join("am.mvn");
    std::fs::write(&path, AM_MVN_TXT)?;
    Ok(load_cmvn(&path)?)
}

/// Python `int(start_ms / 1000 * 16000)`：先做浮点乘除再向零截断。
fn ms_to_sample(ms: i64) -> usize {
    (ms as f64 / 1000.0 * SR as f64) as usize
}

/// 按 VAD 段的起止毫秒切出参考实现送的同一段 wave（尾端按 wave 长度截断）。
fn slice_span(wave: &[i16], start_ms: i64, end_ms: i64) -> &[i16] {
    let a = ms_to_sample(start_ms).min(wave.len());
    let b = ms_to_sample(end_ms).min(wave.len());
    &wave[a..b.max(a)]
}

fn extract(
    wave: &[i16],
    cfg: &funasr_subtitle_rs::frontend::FrontendConfig,
    cmvn: &Cmvn,
) -> Result<Features, Box<dyn std::error::Error>> {
    Ok(extract_features(wave, SR as u32, cfg, Some(cmvn))?)
}

/// 逐元素比较；形状不符时返回 None。
fn max_abs_diff(got: &Array2<f32>, want: &[f32]) -> Option<f32> {
    if got.len() != want.len() {
        return None;
    }
    let mut worst = 0.0f32;
    for (i, (&g, &w)) in got.iter().zip(want.iter()).enumerate() {
        let d = (g - w).abs();
        if !d.is_finite() {
            println!("  非有限值 @ {i}: got {g} want {w}");
            return Some(f32::INFINITY);
        }
        worst = worst.max(d);
    }
    Some(worst)
}

fn assert_matches(
    label: &str,
    feats: &Features,
    want: &[f32],
    rows: usize,
    cols: usize,
) -> Result<f32, Box<dyn std::error::Error>> {
    if feats.feats.dim() != (rows, cols) {
        return Err(format!(
            "{label}: 形状不符，Rust {:?} vs golden ({rows}, {cols})",
            feats.feats.dim()
        )
        .into());
    }
    if feats.feats_len != rows {
        return Err(format!("{label}: feats_len {} vs golden {rows}", feats.feats_len).into());
    }
    let Some(worst) = max_abs_diff(&feats.feats, want) else {
        return Err(format!(
            "{label}: 元素个数不符 {} vs {}",
            feats.feats.len(),
            want.len()
        )
        .into());
    };
    println!("  {label}: max abs diff = {worst:.3e}（{rows}×{cols}）");
    if worst.is_nan() || worst > ATOL {
        return Err(format!("{label}: max abs diff {worst:.3e} 超过 {ATOL:.0e}").into());
    }
    Ok(worst)
}

/// 1) 三个 fixture 的顶层 feats.f32bin（= 段 0 的输出）。
#[test]
fn fixture_feats_match_golden() -> TestResult {
    let cmvn = golden_cmvn()?;
    let cfg = sensevoice_frontend();
    let root = golden_root();
    let mut worst_all = 0.0f32;
    for fixture in FIXTURES {
        println!("[{fixture}]");
        let wave = read_s16(&root.join("input").join(fixture).join("input.s16bin"))?;
        let dir = root.join("sensevoice").join(fixture);
        let meta = read_json(&dir.join("span.json"))?;
        let (start_ms, end_ms, rows, cols) = (
            meta["start_ms"].as_i64().ok_or("span.json 缺 start_ms")?,
            meta["end_ms"].as_i64().ok_or("span.json 缺 end_ms")?,
            meta["feats_len"].as_u64().ok_or("span.json 缺 feats_len")? as usize,
            read_json(&dir.join("feats.json"))?["shape"][1]
                .as_u64()
                .ok_or("feats.json 缺 shape[1]")? as usize,
        );
        let want = read_f32(&dir.join("feats.f32bin"))?;
        let feats = extract(slice_span(&wave, start_ms, end_ms), &cfg, &cmvn)?;
        worst_all = worst_all.max(assert_matches(fixture, &feats, &want, rows, cols)?);
    }
    println!("三个 fixture 最差 max abs diff = {worst_all:.3e}");
    Ok(())
}

/// 2) 段级：按 span.json 的 start_ms/end_ms 切段，逐段与 golden 对拍。
#[test]
fn vad_span_feats_match_golden() -> TestResult {
    let cmvn = golden_cmvn()?;
    let cfg = sensevoice_frontend();
    let root = golden_root();
    let mut spans = 0usize;
    let mut worst_all = 0.0f32;
    for fixture in FIXTURES {
        let wave = read_s16(&root.join("input").join(fixture).join("input.s16bin"))?;
        let dir = root.join("sensevoice").join(fixture);
        let index = read_json(&dir.join("index.json"))?;
        let list = index["spans"].as_array().ok_or("index.json 缺 spans")?;
        for (i, _) in list.iter().enumerate() {
            let span_dir = dir.join("spans").join(format!("span_{i:03}"));
            let meta = read_json(&span_dir.join("span.json"))?;
            let start_ms = meta["start_ms"].as_i64().ok_or("span.json 缺 start_ms")?;
            let end_ms = meta["end_ms"].as_i64().ok_or("span.json 缺 end_ms")?;
            let rows = meta["feats_len"].as_u64().ok_or("缺 feats_len")? as usize;
            let cols = read_json(&span_dir.join("feats.json"))?["shape"][1]
                .as_u64()
                .ok_or("feats.json 缺 shape[1]")? as usize;
            let want = read_f32(&span_dir.join("feats.f32bin"))?;
            let feats = extract(slice_span(&wave, start_ms, end_ms), &cfg, &cmvn)?;
            let label = format!("{fixture}/span_{i:03} [{start_ms},{end_ms}]ms");
            worst_all = worst_all.max(assert_matches(&label, &feats, &want, rows, cols)?);
            spans += 1;
        }
    }
    println!("{spans} 个 VAD 段最差 max abs diff = {worst_all:.3e}");
    assert!(spans >= 3, "至少要覆盖 3 个段，实际 {spans}");
    Ok(())
}

/// 3) Paraformer 预设：golden 里没有 paraformer 的 feats 中间量
///    （`tests/golden/paraformer/*` 只有 preds/segments/text，没 dump feats），
///    但它的 config.yaml frontend_conf 与 am.mvn 与 SenseVoice 逐字段/逐字节相同，
///    因此用同一份 sample_zh 段级 golden 校验这套预设的接线。
#[test]
fn paraformer_frontend_matches_sample_zh_span_golden() -> TestResult {
    let sv = sensevoice_frontend();
    let pf = paraformer_frontend();
    assert_eq!(sv.n_mels, pf.n_mels);
    assert_eq!(sv.frame_length_ms, pf.frame_length_ms);
    assert_eq!(sv.frame_shift_ms, pf.frame_shift_ms);
    assert_eq!(sv.preemphasis, pf.preemphasis);
    assert_eq!(sv.dither, pf.dither);
    assert_eq!((sv.lfr_m, sv.lfr_n), (pf.lfr_m, pf.lfr_n));

    let cmvn = golden_cmvn()?;
    let root = golden_root();
    let wave = read_s16(&root.join("input").join("sample_zh").join("input.s16bin"))?;
    let dir = root
        .join("sensevoice")
        .join("sample_zh")
        .join("spans")
        .join("span_000");
    let meta = read_json(&dir.join("span.json"))?;
    let start_ms = meta["start_ms"].as_i64().ok_or("缺 start_ms")?;
    let end_ms = meta["end_ms"].as_i64().ok_or("缺 end_ms")?;
    let rows = meta["feats_len"].as_u64().ok_or("缺 feats_len")? as usize;
    let want = read_f32(&dir.join("feats.f32bin"))?;
    let feats = extract(slice_span(&wave, start_ms, end_ms), &pf, &cmvn)?;
    println!("[paraformer 预设 / sample_zh span_000]");
    assert_matches("paraformer/sample_zh/span_000", &feats, &want, rows, 560)?;
    Ok(())
}

/// 4) load_cmvn：内嵌的真 am.mvn（560 维）与小样例都要能读，坏文件要报错。
#[test]
fn load_cmvn_reads_embedded_model_file() -> TestResult {
    let cmvn = golden_cmvn()?;
    assert_eq!(cmvn.mean.len(), 560, "am.mvn 的 mean 维度");
    assert_eq!(cmvn.istd.len(), 560, "am.mvn 的 istd 维度");
    assert!((cmvn.mean[0] + 8.311_879).abs() < 1e-5, "{}", cmvn.mean[0]);
    assert!((cmvn.istd[0] - 0.155_775).abs() < 1e-6, "{}", cmvn.istd[0]);
    assert!(
        (cmvn.mean[559] + 11.712_08).abs() < 1e-4,
        "{}",
        cmvn.mean[559]
    );

    // 小样例：3 维，验证解析规则（丢掉 <LearnRateCoef> <0> [ 与末尾 ]）
    let dir = tempfile::tempdir()?;
    let path = dir.path().join("am.mvn");
    std::fs::write(
        &path,
        "<Nnet>\n<Splice> 3 3\n[ 0 ]\n<AddShift> 3 3\n\
         <LearnRateCoef> 0 [ -1.5 0.25 2 ]\n<Rescale> 3 3\n\
         <LearnRateCoef> 0 [ 0.5 2 0.125 ]\n",
    )?;
    let small = load_cmvn(&path)?;
    assert_eq!(small.mean, vec![-1.5, 0.25, 2.0]);
    assert_eq!(small.istd, vec![0.5, 2.0, 0.125]);

    // 坏文件：缺 <Rescale>
    let broken = dir.path().join("broken.mvn");
    std::fs::write(&broken, "<AddShift> 3 3\n<LearnRateCoef> 0 [ 1 2 3 ]\n")?;
    assert!(load_cmvn(&broken).is_err(), "缺 <Rescale> 应报错");
    assert!(load_cmvn(&dir.path().join("absent.mvn")).is_err());
    Ok(())
}

